t.script:

(function(){
  var bar=document.getElementById('waBar');
  var agree=document.getElementById('waAgree');
  var btnLogin=document.getElementById('waLogin');
  var btnPasskey=document.getElementById('waPasskey');
  var root=document.querySelector('.wa-root');
  function update(){
    var sc=document.documentElement.scrollTop||root.scrollTop||0;
    var h=(document.documentElement.scrollHeight - document.documentElement.clientHeight);
    var pct=Math.max(0,Math.min(100,Math.round((sc/h)*100)));
    bar.style.width=pct+'%';
    var ok=(pct>=95)&&agree.checked;
    btnLogin.classList.toggle('wa-disabled',!ok);
    btnPasskey.classList.toggle('wa-disabled',!ok);
  }
  window.addEventListener('scroll',update);
  agree.addEventListener('change',update);
  update();
  btnPasskey.addEventListener('click',function(e){
    e.preventDefault();
    alert('通行密钥登录即将启用；当前请使用密码登录。');
  });
})();
